    x...@0.9100;
    x...@0.9100;
    x...@0.9100;
    x...@0.9100;
    x...@0.9100;
    x...@0.9100;
    x...@0.9100;
    x...@0.9100;
    x...@0.9100;
    [x...@0.02];
    [x...@0.12];
    [x...@0.22];
    [x...@0.32];
    [x...@0.42];
    [x...@0.52];
    [x...@0.62];
    [x...@0.72];
    [x...@0.82];
    [x...@0.92];
    f1@1;
    ANALYSIS:
    type=general;
    estimator=bayes;
    processor=2;
    chains=2;
    biterations=50000(10000);
    thin=1;
    MODEL:
    f1 by x1*0.3000(a1);
    f1 by x2*0.3000(a2);
    f1 by x3*0.3000(a3);
    f1 by x4*0.3000(a4);
