    f1 by x7*0.3000(a7);
    f1 by x8*0.3000(a8);
    f1 by x9*0.3000(a9);
    f1 by x10*0.3000(a10);
    x1*0.9100;
    x2*0.9100;
    x3*0.9100;
    x4*0.9100;
    x5*0.9100;
    x6*0.9100;
    x7*0.9100;
    x8*0.9100;
    x9*0.9100;
    x10*0.9100;
    [x1*0.02];
    [x2*0.12];
    [x3*0.22];
    [x4*0.32];
    [x5*0.42];
    [x6*0.52];
    [x7*0.62];
    [x8*0.72];
    [x9*0.82];
    [x10*0.92];
    f1@1;
    model priors:
    a1-a10~N([[facpm]],[[facpv]]);
    output:tech9;", fill=T)
sink()
createModels(paste0( "d:/fanlin/datagene1.inp"))
sink("datagene2.inp")
